    /** Inline SVG (decorative: aria-hidden) for an icon name, or '' when unknown. */
    public static function svg(string $name, int $size = 18, string $class = ''): string
    {
        $inner = self::PATHS[$name] ?? null;
        if ($inner === null) {
            return '';
        }
        $cls = trim('lucide '.$class);

        return '<svg xmlns="http://www.w3.org/2000/svg" width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" class="'.e($cls).'" aria-hidden="true" focusable="false">'.$inner.'</svg>';
    }
